1235→            <TextField
1236→              label="Title"
1237→              value={editTitle}
1238→              onChange={setEditTitle}
1239→              placeholder="e.g. Export ZIP codes to CSV"
1240→              autoComplete="off"
1241→              maxLength={150}
1242→              showCharacterCount
1243→              helpText="Keep it short and descriptive."
1244→            />
1245→            <TextField
1246→              label="Description"
1247→              value={editDescription}
1248→              onChange={setEditDescription}
1249→              placeholder="Describe the feature and why it would be valuable..."
1250→              autoComplete="off"
1251→              multiline={4}
1252→              maxLength={MAX_DESCRIPTION_LENGTH}
1253→              showCharacterCount
1254→              helpText="The more context you provide, the better we can understand your needs."
1255→            />
1256→            <Select
1257→              label="Category"
1258→              options={CATEGORY_OPTIONS}
1259→              value={editCategory}
1260→              onChange={setEditCategory}
1261→              helpText="Choose the category that best fits your request."
1262→            />
1263→          </BlockStack>
1264→        </Modal.Section>
