      <p style="margin:0 0 6px;font-weight:600;color:#202223;font-size:15px;">Pinzo</p>
      <p style="margin:0 0 4px;">This widget requires the app embed to be enabled.</p>
      <p style="margin:0;font-size:12px;">Go to <strong>App Embeds</strong> and toggle on <strong>Pinzo</strong> to activate.</p>
    </div>
    <!-- Active preview (hidden by default) -->
    <div id="zcc-active-{{ block.id }}" style="display:none;">
      <div style="
        background:#ffffff;
        border:none;
        border-radius:12px;
        padding:24px;
        max-width:480px;
        font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
        box-sizing:border-box;
