              </Text>
            </Banner>
          </Layout.Section>
        )}
        {hasFiniteLimit && (
          <Layout.Section>
            <InlineStack align="end">
              <Badge
                tone={
                  (rules as Rule[]).length >= limits.maxDeliveryRules
                    ? "warning"
                    : undefined
                }
              >
                {`${(rules as Rule[]).length}/${limits.maxDeliveryRules} rules used`}
              </Badge>
            </InlineStack>
          </Layout.Section>
        )}
        <Layout.Section>
          <Card padding="0">
            {(rules as Rule[]).length === 0 ? (
              <EmptyState
                heading="No delivery rules yet"
                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
                action={
                  isFreePlan
                    ? {
                        content: "Upgrade to create rules",
                        onAction: () => navigate("/app/pricing"),
                      }
                    : {
                        content: "Create your first rule",
                        onAction: openCreate,
                      }
                }
              >
                <Text as="p">
                  Delivery rules let you set fees, minimum order amounts,
                  estimated delivery times, and delivery schedules for different
                  zones. Rules are evaluated by priority order.
                </Text>
              </EmptyState>
            ) : (
              <DataTable
                columnContentTypes={[
                  "text",
                  "text",
                  "text",
                  "text",
                  "text",
                  "text",
                  "text",
                ]}
                headings={[
                  "Rule Name",
                  "Zone",
                  "Delivery Fee",
                  "Min. Order",
                  "ETA",
                  "Days",
                  "Actions",
                ]}
                rows={tableRows}
                hoverable
              />
            )}
          </Card>
        </Layout.Section>
      </Layout>
      </Box>

      {/* Create / Edit Modal */}
      <Modal
        open={modalOpen}
        onClose={() => {
          setModalOpen(false);
          resetForm();
        }}
        title={editingRule ? "Edit Delivery Rule" : "Create Delivery Rule"}
        primaryAction={{
          content: editingRule ? "Save Changes" : "Create Rule",
          onAction: handleSave,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setModalOpen(false);
              resetForm();
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {actionError && <Banner tone="critical">{actionError}</Banner>}

            <TextField
              label="Rule Name"
              value={name}
              onChange={setName}
              placeholder="e.g. Manhattan Standard Delivery"
              autoComplete="off"
              helpText="A descriptive name for this delivery rule."
            />

            <InlineGrid columns={2} gap="300">
              <Select
                label="Zone"
                options={zoneOptions}
                value={zone}
                onChange={setZone}
                helpText="Apply this rule to a specific zone, or all zones."
              />
              <TextField
                label="Priority"
                type="number"
                value={priority}
                onChange={setPriority}
                autoComplete="off"
                helpText="Lower number = higher priority."
              />
            </InlineGrid>

            <TextField
              label="Specific Zip Codes (optional)"
              value={zipCodes}
              onChange={setZipCodes}
              placeholder="10001, 10002, 10003"
              autoComplete="off"
              helpText="Comma-separated zip codes. Leave empty to apply to all zip codes in the zone."
            />

            <Divider />
            <Text as="h3" variant="headingSm">
              Pricing
            </Text>

            <InlineGrid columns={2} gap="300">
              <TextField
                label="Delivery Fee ($)"
                type="number"
                value={deliveryFee}
                onChange={setDeliveryFee}
                placeholder="0.00"
                autoComplete="off"
                helpText="Leave empty for free delivery."
              />
              <TextField
                label="Min. Order Amount ($)"
                type="number"
                value={minOrderAmount}
                onChange={setMinOrderAmount}
                placeholder="0.00"
                autoComplete="off"
                helpText="Minimum order to qualify for delivery."
              />
            </InlineGrid>

            <TextField
              label="Free Shipping Above ($)"
              type="number"
              value={freeShippingAbove}
              onChange={setFreeShippingAbove}
              placeholder="e.g. 50.00"
              autoComplete="off"
              helpText="Waive the delivery fee for orders above this amount."
            />

            <Divider />
            <Text as="h3" variant="headingSm">
              Schedule
            </Text>

            <InlineGrid columns={2} gap="300">
              <TextField
                label="Estimated Delivery"
                value={estimatedDays}
                onChange={setEstimatedDays}
                placeholder="e.g. 2-3 days"
                autoComplete="off"
              />
              <TextField
                label="Order Cutoff Time"
                value={cutoffTime}
                onChange={setCutoffTime}
                placeholder="e.g. 14:00"
                autoComplete="off"
                helpText="Orders after this time ship next delivery day."
              />
            </InlineGrid>

            <BlockStack gap="200">
              <Text as="p" variant="bodyMd">
                Delivery Days
              </Text>
              <InlineStack gap="300" wrap>
                {DAYS_OPTIONS.map((day) => (
                  <Checkbox
                    key={day.value}
                    label={day.label}
                    checked={selectedDays.includes(day.value)}
                    onChange={() => toggleDay(day.value)}
                  />
                ))}
              </InlineStack>
            </BlockStack>
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export function ErrorBoundary() {
  return boundary.error(useRouteError());
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

