      <Modal
        open={notifyModalOpen}
        onClose={() => setNotifyModalOpen(false)}
        title="Confirm Notify Selected ZIP Codes"
        primaryAction={{
          content: `Notify ${selectedZipCustomerCount} Customer${selectedZipCustomerCount === 1 ? "" : "s"}`,
