      >
        <Modal.Section>
          <BlockStack gap="400">
            {notifyResult && notifyResult.count > 0 ? (
              <>
                {notifyResult.emailsSent != null && notifyResult.emailsSent > 0 ? (
                  <Banner tone="success">
