                    {notifyResult.count} customer
                    {notifyResult.count === 1 ? "" : "s"} for ZIP code{" "}
                    {notifyResult.zipCode}.
                  </Banner>
                ) : notifyResult.emailsSent === 0 ? (
                  <Banner tone="warning">
